CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text, display_name text, totp_secret text, created_at timestamptz NOT NULL DEFAULT now(), disabled_at timestamptz);
CREATE TABLE IF NOT EXISTS sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions(user_id);
CREATE TABLE IF NOT EXISTS oauth_identities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), provider text NOT NULL, provider_subject text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider, provider_subject));
CREATE TABLE IF NOT EXISTS oauth_states (state_hash text PRIMARY KEY, provider text NOT NULL, verifier text NOT NULL, nonce text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS otp_challenges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL, purpose text NOT NULL, code_hash text NOT NULL, attempts integer NOT NULL DEFAULT 0, expires_at timestamptz NOT NULL, consumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS otp_email_idx ON otp_challenges(email, created_at DESC);
CREATE TABLE IF NOT EXISTS organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), organization_id uuid NOT NULL REFERENCES organizations(id), role text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,organization_id));
CREATE INDEX IF NOT EXISTS memberships_org_idx ON memberships(organization_id);
CREATE TABLE IF NOT EXISTS api_keys (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, token_prefix text NOT NULL UNIQUE, token_hash text NOT NULL, scopes jsonb NOT NULL DEFAULT '["inference:invoke"]'::jsonb, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz);
CREATE TABLE IF NOT EXISTS models (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), public_name text NOT NULL, upstream_name text NOT NULL, context_window integer NOT NULL DEFAULT 8192, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,public_name));
CREATE TABLE IF NOT EXISTS deployments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), model_id uuid NOT NULL REFERENCES models(id), status text NOT NULL DEFAULT 'configured', runtime_profile text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS quotas (organization_id uuid PRIMARY KEY REFERENCES organizations(id), monthly_limit bigint NOT NULL DEFAULT 1000000, concurrent_limit integer NOT NULL DEFAULT 3);
CREATE TABLE IF NOT EXISTS quota_buckets (organization_id uuid NOT NULL REFERENCES organizations(id), period text NOT NULL, used_tokens bigint NOT NULL DEFAULT 0, reserved_tokens bigint NOT NULL DEFAULT 0, in_flight integer NOT NULL DEFAULT 0, UNIQUE(organization_id,period), CHECK (used_tokens>=0 AND reserved_tokens>=0 AND in_flight>=0));
CREATE TABLE IF NOT EXISTS inference_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), model_id uuid NOT NULL REFERENCES models(id), status text NOT NULL, prompt_tokens integer NOT NULL DEFAULT 0, completion_tokens integer NOT NULL DEFAULT 0, elapsed_ms integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS inference_requests_org_created ON inference_requests(organization_id,created_at);
CREATE TABLE IF NOT EXISTS benchmarks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), model_id uuid NOT NULL REFERENCES models(id), status text NOT NULL DEFAULT 'queued', configuration jsonb NOT NULL, results jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid REFERENCES organizations(id), actor_id uuid REFERENCES users(id), action text NOT NULL, resource_type text NOT NULL, resource_id text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_org_created ON audit_events(organization_id,created_at DESC);
